INSERT INTO `PLAYGROUND` (`ID`, `USUARIO`, `NOME`, `HTML`, `TASK_ID`, `SHARE_TOKEN`, `CHAVE_IA`, `CONVERSA`, `ATIVO`, `CRIADO_EM`, `ATUALIZADO_EM`) VALUES
(2, 7, 'Concentração de gastos por fornecedor em 2026 — sem lançamentos na base', '<!DOCTYPE html>\n<html lang="pt-BR">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Concentração de gastos por fornecedor — 2026</title>\n<style>\n*{box-sizing:border-box}\nbody{margin:0;background:#f8fafc;color:#0f172a;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;-webkit-font-smoothing:antialiased}\n.wrap{max-width:1000px;margin:0 auto;padding:32px 24px 48px}\nh1{font-size:22px;font-weight:600;margin:0 0 6px;letter-spacing:-.01em}\n.sub{color:#64748b;font-size:14px;margin:0 0 24px}\n.card{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:20px 22px;margin-bottom:16px}\n.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:16px}\n.kpi{background:#fff;border:1px solid #e2e8f0;border-radius:12px;padding:16px 18px}\n.kpi .lab{color:#64748b;font-size:11px;text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px}\n.kpi .val{font-size:26px;font-weight:600;text-align:right;font-variant-numeric:tabular-nums;letter-spacing:-.02em;line-height:1.1}\n.kpi .hint{color:#64748b;font-size:12px;text-align:right;margin-top:6px;line-height:1.4}\n.ct{font-size:15px;font-weight:600;margin:0 0 4px}\n.cs{color:#64748b;font-size:13px;margin:0 0 18px;line-height:1.5}\ntable{width:100%;border-collapse:collapse;font-size:13px}\nth{text-align:left;color:#64748b;font-weight:500;font-size:11px;text-transform:uppercase;letter-spacing:.05em;padding:0 10px 10px;border-bottom:1px solid #e2e8f0}\nth.r,td.r{text-align:right}\ntd{padding:11px 10px;border-bottom:1px solid #f1f5f9;font-variant-numeric:tabular-nums}\ntbody tr:last-child td{border-bottom:none}\n.zero{color:#64748b}\n.aviso{display:flex;gap:14px;background:#fffbeb;border:1px solid #fde68a;border-radius:12px;padding:18px 20px;margin-bottom:16px}\n.aviso .mk{color:#d97706;font-weight:600;font-size:13px;white-space:nowrap}\n.aviso p{margin:0;font-size:13px;line-height:1.6}\n.aviso p+p{margin-top:8px}\n.foot{color:#64748b;font-size:12px;line-height:1.65;border-top:1px solid #e2e8f0;padding-top:16px}\n.foot b{color:#0f172a;font-weight:600}\n.leg{display:flex;flex-wrap:wrap;gap:18px;margin-top:14px;color:#64748b;font-size:12px}\n.leg span{display:flex;align-items:center;gap:7px}\n.sw{width:11px;height:11px;border-radius:3px;display:inline-block}\n</style>\n</head>\n<body>\n<div class="wrap">\n\n  <h1>Concentração de gastos por fornecedor — 2026</h1>\n  <p class="sub">Contas a pagar · período de 1º de janeiro a 4 de novembro de 2026</p>\n\n  <div class="kpis">\n    <div class="kpi">\n      <div class="lab">Gasto do ano</div>\n      <div class="val">R$ 0,00</div>\n      <div class="hint">nenhuma nota no período</div>\n    </div>\n    <div class="kpi">\n      <div class="lab">Fornecedores com gasto</div>\n      <div class="val">0</div>\n      <div class="hint">nenhum CNPJ movimentado</div>\n    </div>\n    <div class="kpi">\n      <div class="lab">Notas registradas</div>\n      <div class="val">0</div>\n      <div class="hint">em 2026 e em todo o histórico</div>\n    </div>\n    <div class="kpi">\n      <div class="lab">Peso dos 5 maiores</div>\n      <div class="val">—</div>\n      <div class="hint">não apurável sem gasto</div>\n    </div>\n  </div>\n\n  <div class="aviso">\n    <div class="mk">Sem registro</div>\n    <div>\n      <p>A base de contas a pagar não tem <b>nenhum lançamento</b> e <b>nenhum documento</b> registrado — nem em 2026, nem em qualquer ano anterior. Por isso não existe gasto a distribuir entre fornecedores e nenhuma concentração pode ser apontada.</p>\n      <p>Não se trata de um filtro restritivo: a consulta foi repetida sem recorte de data e sem recorte de situação, e o resultado continuou em zero. Os cadastros de apoio (empresas, naturezas, centros, contas) estão carregados, o que indica base configurada e ainda sem movimento.</p>\n    </div>\n  </div>\n\n  <div class="card">\n    <p class="ct">Distribuição do gasto por fornecedor</p>\n    <p class="cs">O gráfico ordena os fornecedores do maior para o menor gasto acumulado no ano. Sem notas registradas, não há barras a desenhar.</p>\n    <svg viewBox="0 0 900 270" width="100%" role="img" aria-label="Gráfico de concentração por fornecedor sem dados no período">\n      <line x1="120" y1="24" x2="120" y2="214" stroke="#e2e8f0" stroke-width="1"></line>\n      <line x1="120" y1="214" x2="860" y2="214" stroke="#cbd5e1" stroke-width="1"></line>\n      <line x1="120" y1="167" x2="860" y2="167" stroke="#f1f5f9" stroke-width="1" stroke-dasharray="4 4"></line>\n      <line x1="120" y1="120" x2="860" y2="120" stroke="#f1f5f9" stroke-width="1" stroke-dasharray="4 4"></line>\n      <line x1="120" y1="73" x2="860" y2="73" stroke="#f1f5f9" stroke-width="1" stroke-dasharray="4 4"></line>\n      <line x1="120" y1="26" x2="860" y2="26" stroke="#f1f5f9" stroke-width="1" stroke-dasharray="4 4"></line>\n      <text x="110" y="218" text-anchor="end" font-family="system-ui, sans-serif" font-size="11" fill="#64748b">R$ 0,00</text>\n      <text x="490" y="112" text-anchor="middle" font-family="system-ui, sans-serif" font-size="14" font-weight="600" fill="#0f172a">Nenhum gasto registrado em 2026</text>\n      <text x="490" y="134" text-anchor="middle" font-family="system-ui, sans-serif" font-size="12" fill="#64748b">As barras por fornecedor aparecem aqui assim que houver notas lançadas.</text>\n      <text x="490" y="244" text-anchor="middle" font-family="system-ui, sans-serif" font-size="11" fill="#64748b">Fornecedores, ordenados por gasto acumulado</text>\n      <text x="24" y="124" text-anchor="middle" font-family="system-ui, sans-serif" font-size="11" fill="#64748b" transform="rotate(-90 24 124)">Gasto no ano (R$)</text>\n    </svg>\n    <div class="leg">\n      <span><i class="sw" style="background:#2E3C50"></i>Gasto por fornecedor (sem valores no período)</span>\n      <span><i class="sw" style="background:#e2e8f0"></i>Eixo em R$ 0,00</span>\n    </div>\n  </div>\n\n  <div class="card">\n    <p class="ct">O que já está cadastrado na base</p>\n    <p class="cs">Contagem real dos cadastros de apoio sincronizados do ERP. É a estrutura que receberá a classificação das notas quando o movimento começar.</p>\n    <svg viewBox="0 0 900 292" width="100%" role="img" aria-label="Quantidade de registros em cada cadastro de apoio">\n      <g font-family="system-ui, sans-serif" font-size="12">\n        <text x="186" y="22" text-anchor="end" fill="#0f172a">Operações (TOPs)</text>\n        <rect x="196" y="8" width="620" height="18" rx="3" fill="#2E3C50"></rect>\n        <text x="824" y="22" fill="#0f172a" font-weight="600">330</text>\n\n        <text x="186" y="60" text-anchor="end" fill="#0f172a">Naturezas</text>\n        <rect x="196" y="46" width="496" height="18" rx="3" fill="#2E3C50"></rect>\n        <text x="700" y="60" fill="#0f172a" font-weight="600">264</text>\n\n        <text x="186" y="98" text-anchor="end" fill="#0f172a">Centros de resultado</text>\n        <rect x="196" y="84" width="244" height="18" rx="3" fill="#2E3C50"></rect>\n        <text x="448" y="98" fill="#0f172a" font-weight="600">130</text>\n\n        <text x="186" y="136" text-anchor="end" fill="#0f172a">Contas bancárias</text>\n        <rect x="196" y="122" width="156" height="18" rx="3" fill="#2E3C50"></rect>\n        <text x="360" y="136" fill="#0f172a" font-weight="600">83</text>\n\n        <text x="186" y="174" text-anchor="end" fill="#0f172a">Tipos de título</text>\n        <rect x="196" y="160" width="86" height="18" rx="3" fill="#2E3C50"></rect>\n        <text x="290" y="174" fill="#0f172a" font-weight="600">46</text>\n\n        <text x="186" y="212" text-anchor="end" fill="#0f172a">Empresas</text>\n        <rect x="196" y="198" width="51" height="18" rx="3" fill="#2F8F3F"></rect>\n        <text x="255" y="212" fill="#0f172a" font-weight="600">27</text>\n\n        <text x="186" y="250" text-anchor="end" fill="#0f172a">Tipos de documento</text>\n        <rect x="196" y="236" width="8" height="18" rx="3" fill="#2E3C50"></rect>\n        <text x="212" y="250" fill="#0f172a" font-weight="600">4</text>\n\n        <text x="186" y="288" text-anchor="end" fill="#0f172a">Aprovadores ativos</text>\n        <rect x="196" y="274" width="4" height="18" rx="3" fill="#d97706"></rect>\n        <text x="208" y="288" fill="#0f172a" font-weight="600">2</text>\n      </g>\n    </svg>\n    <div class="leg">\n      <span><i class="sw" style="background:#2E3C50"></i>Cadastro de classificação</span>\n      <span><i class="sw" style="background:#2F8F3F"></i>Empresas, todas ativas</span>\n      <span><i class="sw" style="background:#d97706"></i>Aprovadores: apenas 2 para 27 empresas</span>\n    </div>\n  </div>\n\n  <div class="card">\n    <p class="ct">Detalhe por situação do lançamento</p>\n    <p class="cs">Todas as situações previstas no fluxo, com a contagem e o valor efetivamente encontrados na base.</p>\n    <table>\n      <thead>\n        <tr>\n          <th>Situação</th>\n          <th>O que significa</th>\n          <th class="r">Notas</th>\n          <th class="r">Valor</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td>Aguardando aprovação</td><td class="zero">Exige decisão de um aprovador</td><td class="r zero">0</td><td class="r zero">R$ 0,00</td></tr>\n        <tr><td>Aprovado</td><td class="zero">Liberado para seguir ao ERP</td><td class="r zero">0</td><td class="r zero">R$ 0,00</td></tr>\n        <tr><td>Lançado</td><td class="zero">Já registrado no ERP</td><td class="r zero">0</td><td class="r zero">R$ 0,00</td></tr>\n        <tr><td>Rejeitado</td><td class="zero">Não segue adiante</td><td class="r zero">0</td><td class="r zero">R$ 0,00</td></tr>\n        <tr><td>Erro</td><td class="zero">Recusado pelo ERP</td><td class="r zero">0</td><td class="r zero">R$ 0,00</td></tr>\n        <tr><td>Revisão de leitura</td><td class="zero">Espera conferência dos dados lidos</td><td class="r zero">0</td><td class="r zero">R$ 0,00</td></tr>\n        <tr><td><b>Total</b></td><td class="zero">—</td><td class="r"><b>0</b></td><td class="r"><b>R$ 0,00</b></td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <div class="card">\n    <p class="foot"><b>Período considerado:</b> 1º de janeiro de 2026 a 4 de novembro de 2026, pela data de emissão do documento.<br>\n    <b>O que a análise considerou:</b> todos os lançamentos de contas a pagar, em qualquer situação — aguardando aprovação, aprovado, lançado, rejeitado, erro e revisão de leitura — agrupados pelo CNPJ do fornecedor, somando o valor total de cada nota. Para descartar erro de recorte, a mesma apuração foi repetida sem filtro de ano e sem filtro de situação.<br>\n    <b>Resultado da base em 4 de novembro de 2026:</b> 0 documentos, 0 lançamentos e 0 itens de lançamento; nenhuma aprovação, nenhum envio ao ERP e nenhuma leitura de robô registrada. Os cadastros de apoio estão carregados: 27 empresas ativas, 330 operações, 264 naturezas, 130 centros de resultado, 83 contas bancárias, 46 tipos de título, 4 tipos de documento e 2 aprovadores.<br>\n    <b>Observação:</b> todos os números desta tela vêm de consultas diretas à base. Nada foi estimado ou projetado.</p>\n  </div>\n\n</div>\n</body>\n</html>', 'qfm4lkQRF1Mc3UGnKTyM', NULL, NULL, '[{"tipo":"usuario","texto":"Onde está concentrado o gasto por fornecedor neste ano?"}]', 1, '2026-11-04T20:33:25', '2026-11-04T20:36:41');
INSERT INTO `ROBO_ANEXO` (`ID`, `EMAIL_ID`, `NOME`, `TIPO`, `TAMANHO`, `HASH_DOCUMENTO`, `ORIGEM_LEITURA`, `CONFIANCA`, `CRITERIOS`, `CAMPOS`, `DECISAO`, `MOTIVO`, `LANCAMENTO_ID`, `DOCUMENTO_ID`, `CHAVE_ERP`, `ARQUIVO_URL`, `CRIADO_EM`) VALUES
